-- Configuración de sesión para evitar sustitución de variables (&) y formato de fecha
SET DEFINE OFF;
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI:SS';

-- NOTA: Ejecutar conectado como el usuario 'red_clinica_user' o
-- habiendo seleccionado el esquema correspondiente.

-- ============================================================================
-- 1. MÓDULO 1: TERRITORIO Y CONVENIOS
-- ============================================================================
-- 1.1 UBICACIONES (Jerarquía Geográfica)
-- ----------------------------------------------------------------------------
COMMIT;

-- 1.2 CLINICAS (Sedes Físicas Asistenciales)
-- ----------------------------------------------------------------------------
COMMIT;

-- 1.3 EMPRESAS (Convenios Corporativos de Salud Ocupacional)
-- ----------------------------------------------------------------------------
COMMIT;

-- 1.4 ASEGURADORAS (Compañías de Seguros de Salud)
-- ----------------------------------------------------------------------------
COMMIT;

-- 1.5 PACIENTES (Expediente Maestro de Pacientes)
-- ----------------------------------------------------------------------------
COMMIT;

-- ============================================================================
-- 2. MÓDULO 2: CUERPO MÉDICO Y CATÁLOGOS CLÍNICOS
-- ============================================================================
-- 2.1 ESPECIALIDADES (Disciplinas Médicas Ofertadas)
-- ----------------------------------------------------------------------------
COMMIT;

-- 2.2 MEDICOS (Ficha Profesional de Médicos Adscritos)
-- ----------------------------------------------------------------------------
COMMIT;

-- 2.3 MEDICOS_ESPECIALIDADES (Acreditaciones N:M Médico-Especialidad)
-- ----------------------------------------------------------------------------
COMMIT;

-- 2.4 ENFERMEDADES (Catálogo CIE-10)
-- ----------------------------------------------------------------------------
COMMIT;

-- 2.5 TIPOS_CONSULTA (Modalidades de Consulta y Tarifa Base)
-- ----------------------------------------------------------------------------
COMMIT;

-- 2.6 PROCEDIMIENTOS (Tarifario de Intervenciones Clínicas)
-- ----------------------------------------------------------------------------
COMMIT;

-- ============================================================================
-- 3. MÓDULO 4 (PREVIO): CATÁLOGO DE TESORERÍA
-- ============================================================================
-- 3.1 FORMAS_PAGO (Medios de Pago Autorizados)
-- ----------------------------------------------------------------------------
COMMIT;

-- ============================================================================
-- 4. MÓDULO 3: ACTO MÉDICO Y EXPEDIENTE CLÍNICO
-- ============================================================================
-- 4.1 CONSULTAS (Encuentros Clínicos)
-- ----------------------------------------------------------------------------
COMMIT;

-- 4.2 DIAGNOSTICOS (Relación N:M Cita con Enfermedades CIE-10)
-- ----------------------------------------------------------------------------
COMMIT;

-- 4.3 CONSULTAS_PROCEDIMIENTOS (Detalle de Procedimientos Realizados)
-- (Nota: SUBTOTAL es columna virtual calculada automáticamente)
-- ----------------------------------------------------------------------------
COMMIT;

-- ============================================================================
-- 5. MÓDULO 4: FACTURACIÓN, COBERTURAS Y TRANSACCIONES DE PAGO
-- ============================================================================
-- 5.1 COBROS_CONSULTA (Cuenta Global Consolidada)
-- (Nota: SALDO_PENDIENTE es columna virtual calculada automáticamente)
-- ----------------------------------------------------------------------------
COMMIT;

-- 5.2 DISTRIBUCION_COBRO (Desglose de Responsabilidad Económica)
-- (Nota: SALDO_PENDIENTE es columna virtual calculada automáticamente)
-- ----------------------------------------------------------------------------
COMMIT;

-- 5.3 TRANSACCIONES_PAGO (Libro Diario Inmutable de Caja)
-- ----------------------------------------------------------------------------
COMMIT;

