INSERT INTO CONSULTAS (ID_PACIENTE, ID_CLINICA, ID_MEDICO, ID_ESPECIALIDAD, ID_TIPO_CONSULTA, FECHA_CONSULTA, PRECIO_CONSULTA, MOTIVO_CONSULTA, PRESCRIPCION) VALUES (1, 1, 1, 1, 1, TO_DATE('2026-03-10', 'YYYY-MM-DD'), 30.00, 'Fiebre alta y dedo quebrado tras caída en jornada laboral', 'Acetaminofén 500mg c/8h por 3 días. Ibuprofeno 400mg c/8h por 4 días. Reposo absoluto de mano derecha.');
INSERT INTO CONSULTAS (ID_PACIENTE, ID_CLINICA, ID_MEDICO, ID_ESPECIALIDAD, ID_TIPO_CONSULTA, FECHA_CONSULTA, PRECIO_CONSULTA, MOTIVO_CONSULTA, PRESCRIPCION) VALUES (2, 1, 1, 2, 2, TO_DATE('2026-03-12', 'YYYY-MM-DD'), 50.00, 'Sensación de oído tapado bilateral y zumbido constante de 5 días de evolución', 'Gotas óticas gliceroladas 3 gotas c/12h por 3 días. No introducir hisopos.');
INSERT INTO CONSULTAS (ID_PACIENTE, ID_CLINICA, ID_MEDICO, ID_ESPECIALIDAD, ID_TIPO_CONSULTA, FECHA_CONSULTA, PRECIO_CONSULTA, MOTIVO_CONSULTA, PRESCRIPCION) VALUES (3, 2, 3, 5, 2, TO_DATE('2026-03-15', 'YYYY-MM-DD'), 50.00, 'Palpitaciones esporádicas y cefalea occipital matutina recurrente', 'Losartán 50mg 1 tab cada mañana. Dieta baja en sodio y control de presión diario.');
INSERT INTO CONSULTAS (ID_PACIENTE, ID_CLINICA, ID_MEDICO, ID_ESPECIALIDAD, ID_TIPO_CONSULTA, FECHA_CONSULTA, PRECIO_CONSULTA, MOTIVO_CONSULTA, PRESCRIPCION) VALUES (4, 1, 1, 1, 1, TO_DATE('2026-03-18', 'YYYY-MM-DD'), 30.00, 'Congestión nasal severa, odinofagia y estornudos frecuentes', 'Loratadina 10mg 1 tab cada noche por 5 días. Solución salina nasal c/6h.');
INSERT INTO CONSULTAS (ID_PACIENTE, ID_CLINICA, ID_MEDICO, ID_ESPECIALIDAD, ID_TIPO_CONSULTA, FECHA_CONSULTA, PRECIO_CONSULTA, MOTIVO_CONSULTA, PRESCRIPCION) VALUES (5, 2, 3, 8, 4, TO_DATE('2026-03-20', 'YYYY-MM-DD'), 20.00, 'Control semestral de hipertensión y chequeo de perfil lipídico', 'Continuar con Enalapril 20mg tab diaria. Mantener caminatas de 30 min diarios.');
